    {
      "@id": "activity:translation-story_text_1-2026-07-08T13:22:13.857708+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:22:13.857708+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_1",
      "@type": "prov:Entity",
      "prov:value": "Aristotle walked as he taught. He believed the act of moving — through space, through questions, through observation — was itself a form of thinking. Two thousand years later, the research agrees."
    },
    {
      "@id": "entity:target-story_text_1-v1",
      "@type": "prov:Entity",
      "prov:value": "אריסטו הלך כפי שדרש. הוא האמין שהעובדה שלעבור - במרחב, בשאלה, באפיון - היא בעצמה סוג של חשיבה. שנתיים אלף שנים אחרי כן, המחקר מסכים.",
      "generated_by": {
        "@id": "activity:translation-story_text_1-2026-07-08T13:22:13.857708+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_1"
      }
    },
    {
      "@id": "activity:translation-story_text_2-2026-07-08T13:22:13.857708+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:22:13.857708+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-story_text_2",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware puts that insight in your pocket. Teachers design activities that bring curriculum to life in the real world. Students explore, capture, and reflect. Peri guides the inquiry. And learning — finally — moves."
    },
    {
      "@id": "entity:target-story_text_2-v1",
      "@type": "prov:Entity",
      "prov:value": "פיריפטטיקווארה מוכן את ההיגיון לך בעוד. מורים מתכננים פעילויות שמביאות תוכנית הלימודים לחיים בשלטון העולמי. סטודנטים חקור, מצלמים ומחשבים. פרי מדריך את החקירה. והלמידה - סוף סוף - נע.",
      "generated_by": {
        "@id": "activity:translation-story_text_2-2026-07-08T13:22:13.857708+00:00"
      },
      "used_source": {
        "@id": "entity:source-story_text_2"
      }
    },
