    {
      "@id": "entity:source-meet_peri.step.1.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri sets the scene and asks your child what they notice. No right answer yet — just looking."
    },
    {
      "@id": "entity:target-meet_peri.step.1.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "פרי מציב את הסצנה ומדבר עם ילדך מה הם רואים. עדיין אין תשובה נכונה - רק צפייה.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.1.desc-2026-07-08T13:41:21.365237+00:00"
      },
      "used_source": {
