      }
    },
    {
      "@id": "activity:translation-meet_peri.step.2.desc-2026-07-08T13:41:21.365237+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:41:21.365237+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.2.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child records what they see, hear, or measure. Peri prompts for specifics if the answer is vague."
    },
    {
      "@id": "entity:target-meet_peri.step.2.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "ילדך רשם מה שהוא רואה, שומע או מדיד. פרי מציע סpecifics אם התשובה אגבית.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.2.desc-2026-07-08T13:41:21.365237+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.2.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.3.desc-2026-07-08T13:41:44.240237+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:41:44.240237+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.3.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri asks comparison and classification questions. What\\'s similar? What\\'s different? What pattern do you see?"
    },
    {
      "@id": "entity:target-meet_peri.step.3.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "פרי שואלת שאלות של השוואה וклаסיפיקציה. מה דומה? מה שונה? מה מראה לך אתר天啊?",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.3.desc-2026-07-08T13:41:44.240237+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.3.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.4.desc-2026-07-08T13:41:44.240237+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:41:44.240237+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.4.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child proposes a cause or mechanism. Peri tests it with evidence questions, not hints."
    },
    {
      "@id": "entity:target-meet_peri.step.4.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "ילדך מציע סיבה או מכניזם. פרי מבחן אותו עם שאלות ראיות, ולא הוכחות.",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.4.desc-2026-07-08T13:41:44.240237+00:00"
      },
      "used_source": {
