      }
    },
    {
      "@id": "activity:translation-meet_peri.step.5.desc-2026-07-08T13:41:44.240237+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-08T13:41:44.240237+00:00",
